import logging
import re

from ute_common_abstract_core.network_elem_identification import UeIdentification
from ute_ue.data_transfers.iperf_data_transfer import IperfDataTransfer
from ute_ue.lteue import LteUe
from moler.config import load_config
from moler.device.device import DeviceFactory
from ute_ue.exceptions import CannotCreateUe
from ute_ue.config import loggers as ta_ue_logging
from moler.exceptions import CommandTimeout


class AtCmdUe(LteUe):
    """At Ue"""
    data_transfer_types = {
        # tool   implementing class
        'iperf': IperfDataTransfer,
    }

    info2cmdname = {
        'ALL': 'get_product_info',
        'IMSI': 'get_imsi',
        'IMEI': 'get_imei',
        'REVISION': 'get_revision_id',
        'MANUFACTURER_ID': 'get_manufacturer_id',
        'ATTACH_STATE': 'get_attach_state'
    }

    LEGACY_INFO = "You are using a legacy plugin. All new features will be developed only in the taf.ue.* projects.\n" \
                  "To preserve support, switch to the taf.ue.at solution:\n" \
                  "https://confluence.ext.net.nokia.com/display/AbstractLibs/taf.ue.at\n"

    # pylint: disable=too-many-instance-attributes, broad-except, unnecessary-pass
    def __init__(self, name, configuration):
        """

        :param name:
        :param configuration:
        """
        super(AtCmdUe, self).__init__(name, configuration)

        self.ne_id = None

        self.name = name

        self.ue_pc_ip = configuration["ue_pc_ip"]
        self.ue_pc_login = configuration["login"]
        self.ue_pc_password = configuration["password"]
        self.ue_pc_prompt = configuration["prompt"]
        self.com_port = configuration["com_port"]
        self.allowed_newline_after_prompt = configuration.get('allowed_newline_after_prompt', True)

        self.logger = ta_ue_logging.LoggerAdapter4EmptyExtra(self.logger, {
            'area': 'UE',
            'ue_id': '{}:{}'.format(self.ue_pc_ip, self.com_port)})
        logging.warning(self.LEGACY_INFO)
        self.logger.warning(self.LEGACY_INFO)
        self._moler_device = self._ensure_connection_and_get_moler_device()
        self._complete_data_transfer_configuration()
        self._create_ue_identification()

    def _create_ue_identification(self):
        ue_identification = '{}:{}'.format(self.ue_pc_ip, self.com_port)
        self.ne_id = UeIdentification(identifiers=[('atcmd', ue_identification)],
                                      network_elem_type='UE',
                                      specific_for_tool='atcmd')

    def _ensure_connection_and_get_moler_device(self):
        at_config = self._create_moler_dev_at_config()
        load_config(config=at_config, config_type='dict')
        try:
            moler_device = DeviceFactory.get_device(name=self.name + '_no_halfduplex', initial_state="AT_REMOTE")
            at_cmd = moler_device.get_cmd(cmd_name="at", cmd_params={})

            at_response = at_cmd()
            if at_response != {}:
                raise CannotCreateUe("Cannot connect to UE PC and execute \"AT\" command.")
            return moler_device
        except CommandTimeout:
            self._release_com_port()
            moler_device = DeviceFactory.get_device(name=self.name + '_halfduplex', initial_state="AT_REMOTE")
            at_cmd = moler_device.get_cmd(cmd_name="at", cmd_params={})

            at_response = at_cmd()
            if at_response != {}:
                raise CannotCreateUe("Cannot connect to UE PC and execute \"AT\" command.")
            return moler_device

    def _create_moler_dev_at_config(self):
        at_config = {
            'DEVICES': {
                self.name + '_no_halfduplex': {
                    'DEVICE_CLASS': 'moler.device.atremote.AtRemote',
                    'CONNECTION_HOPS': {
                        'UNIX_LOCAL': {
                            'UNIX_REMOTE': {
                                'execute_command': 'ssh',
                                'command_params': {
                                    'expected_prompt': self.ue_pc_prompt,
                                    'host': self.ue_pc_ip,
                                    'login': self.ue_pc_login,
                                    'password': self.ue_pc_password,
                                    'allowed_newline_after_prompt': self.allowed_newline_after_prompt}}},
                        'UNIX_REMOTE': {
                            'AT_REMOTE': {
                                'execute_command': 'cu',
                                'command_params': {
                                    'serial_devname': '{}'.format(self.com_port)}}}}},
                self.name + '_halfduplex': {
                    'DEVICE_CLASS': 'moler.device.atremote.AtRemote',
                    'CONNECTION_HOPS': {
                        'UNIX_LOCAL': {
                            'UNIX_REMOTE': {
                                'execute_command': 'ssh',
                                'command_params': {
                                    'expected_prompt': self.ue_pc_prompt,
                                    'host': self.ue_pc_ip,
                                    'login': self.ue_pc_login,
                                    'password': self.ue_pc_password,
                                    'allowed_newline_after_prompt': self.allowed_newline_after_prompt}}},
                        'UNIX_REMOTE': {
                            'AT_REMOTE': {
                                'execute_command': 'cu',
                                'command_params': {
                                    'serial_devname': '{}'.format(self.com_port),
                                    'options': '-h'}}}}}
            }}
        return at_config

    def _complete_data_transfer_configuration(self):
        ue_host_dict = {"host": self.ue_pc_ip,
                        "login": self.ue_pc_login,
                        "password": self.ue_pc_password,
                        "expected_prompt": self.ue_pc_prompt,
                        "allowed_newline_after_prompt": self.allowed_newline_after_prompt}

        # if "adb" in self._configuration["data_transfer"].keys():
        #     adb_dict = self._configuration["data_transfer"].pop("adb")
        #     ue_host_dict['adb'] = adb_dict

        self._configuration["data_transfer"]["ue_host"] = ue_host_dict
        self.logger.debug("UE config dict after completing info about data transfer: {}".format(self._configuration))

    def _get_ue_ip(self, context_identifier=1):
        self._moler_device.goto_state("AT_REMOTE")
        get_ip_cmd = self._moler_device.get_cmd(cmd_name="get_ip",
                                                cmd_params={'context_identifier': context_identifier})
        get_ip_response = get_ip_cmd()
        return get_ip_response['ip']

    def _get_apns_list(self):
        self._moler_device.goto_state("AT_REMOTE")
        get_apns_cmd = self._moler_device.get_cmd(cmd_name="get_apns")
        apns_list = get_apns_cmd()
        return apns_list

    def _resolve_apn_name_into_ip(self, apn_name):
        apns_list = self._get_apns_list()
        for apn in apns_list:
            if apn['apn_name'] == apn_name:
                return self._get_ue_ip(apn['apn_num'])
        raise ValueError("APN {} not found.".format(apn_name))

    def __str__(self):
        return "{}({})".format(self.__class__.__name__, self.name if hasattr(self, "name") else '')

    def __repr__(self):
        return "{}({}, at {})".format(self.__class__.__name__, self.name if hasattr(self, "name") else '',
                                      hex(id(self)))

    def _release_com_port(self):
        unix_config = self._create_moler_dev_unix_config()

        load_config(config=unix_config, config_type='dict')

        unix_remote_device = DeviceFactory.get_device(name='UNIX_REMOTE_DEVICE', initial_state="UNIX_REMOTE")
        ps_cmd = unix_remote_device.get_cmd(cmd_name="ps", cmd_params={'options': '-aux'})
        ps_response = ps_cmd()

        # cu -l /dev/ttyS21 -s 19200 -E -
        _re_ttyS = r'.*\/dev\/ttyS{}.*'.format(self.com_port)

        for cmd in ps_response:
            if re.match(_re_ttyS, cmd['COMMAND']):
                kill_cmd = unix_remote_device.get_cmd(cmd_name="kill", cmd_params={'pid': str(cmd['PID']),
                                                                                   'options': '-9'})
                kill_cmd()

    def _create_moler_dev_unix_config(self):
        unix_config = {
            'DEVICES': {
                'UNIX_REMOTE_DEVICE': {
                    'DEVICE_CLASS': 'moler.device.unixremote.UnixRemote',
                    'CONNECTION_HOPS': {
                        'UNIX_LOCAL': {
                            'UNIX_REMOTE': {
                                'execute_command': 'ssh',
                                'command_params': {
                                    'expected_prompt': self.ue_pc_prompt,
                                    'host': self.ue_pc_ip,
                                    'login': self.ue_pc_login,
                                    'password': self.ue_pc_password,
                                    'allowed_newline_after_prompt': self.allowed_newline_after_prompt}}}}}}}
        return unix_config

    def shutdown(self):
        """
        Placeholder for Ue specific cleanups
        :return:
        """
        self._release_com_port()

    def attach(self, timeout=-1, **kwargs):
        """
        Perform attach on UE.

        :return: None
        """
        self._moler_device.goto_state("AT_REMOTE")
        attach_cmd = self._moler_device.get_cmd(cmd_name="attach", cmd_params={})
        attach_cmd()

    def detach(self, timeout=-1, **kwargs):
        """
        Perform detach on UE.
        No action if UE is already detached.

        :return: None
        """
        self._moler_device.goto_state("AT_REMOTE")
        detach_cmd = self._moler_device.get_cmd(cmd_name="detach", cmd_params={})
        detach_cmd()

    def _create_data_transfer(self, name, dt_definition):
        """
        Creating IperfDataTransfer object.

        :param name: name to be assigned to starting transfer. You must use it later on to reference given transfer.
        :param dt_definition: object of DataTransferDefinition that encapsulates all needed parameters.
        :return: AtCmdDataTransfer: object derived from iperf_data_transfer class
        """
        # selecting which data transfer type to use is based on two sources:
        # 1) dt_definition that comes from test and speaks in protocol terms (duration, direction, bearer, ...)
        # 2) 'data transfer' field of ue configuration that speaks in tool and lab related terms (unix cmd, IP, port ..)
        if 'data_transfer' in self._configuration:
            dt_configuration = dict(self._configuration['data_transfer'])

            if 'ue_ip' not in dt_configuration and 'apn' not in dt_definition.protocol_details:
                raise KeyError("You have to provide ue_ip in yaml configuration "
                               "or 'apn' parameter in Start Data Transfer keyword.")
            if 'ue_ip' not in dt_configuration:
                ip = self._resolve_apn_name_into_ip(dt_definition.protocol_details['apn'])
                if ip == '0.0.0.0':
                    self.logger.warning("IP is {}. Probably UE is not attached.".format(ip))
                dt_configuration['ue_ip'] = ip

            requested_protocol = dt_definition.protocol
            ue_known_transfer_types = dt_configuration.pop('type', {})
            tool = self._get_requested_tool(requested_protocol, ue_known_transfer_types)
            dt_implementation = self.data_transfer_types.get(tool, IperfDataTransfer)

            data_transfer = dt_implementation(name, dt_definition, dt_configuration, logger_name=self.ue_logger_name)
        else:
            data_transfer = IperfDataTransfer(name, dt_definition, self._configuration, logger_name=self.ue_logger_name)
        return data_transfer

    def _get_requested_tool(self, requested_protocol, ue_known_transfer_types=None):
        default_transfer_types = {
            'udp': 'iperf',  # iperf is default tool for udp traffic
            'tcp': 'iperf',  # iperf is default tool for tcp traffic
            'icmp': 'ping',  # ping is default tool for icmp traffic
        }
        transfer_types = default_transfer_types
        if ue_known_transfer_types:
            transfer_types.update(ue_known_transfer_types)
        tool = transfer_types.get(requested_protocol, 'unknown')
        return tool

    def log_ue_info(self, info):
        """
        Logs specified UE information

        :param infos_list: List of information to be logged, 'ALL' by default.
        :return: None
        """
        if info in list(self.info2cmdname.keys()):
            cmd_name = self.info2cmdname[info]
            query_cmd = self._moler_device.get_cmd(cmd_name=cmd_name, cmd_params={})
            queried_value = query_cmd()
            print('-' * 30)
            for key in queried_value:
                print('{}: {}'.format(key, queried_value[key]))
            print('-' * 30)
        else:
            print("'{}' is not supported. Supported parameters: {}".format(info, list(self.info2cmdname.keys())))
            self.logger.warning(
                "'{}' is not supported. Supported parameters: {}".format(info, list(self.info2cmdname.keys())))

    def validate_ue_info(self, info, expected_value):
        """
        Validates specified UE information

        :param info: Info type we want to check, e.g. IP, Cell ID etc.
        :param expected_value: Value that the specified info should have.
        :return: None
        """
        info2cmdname_without_ALL = self.info2cmdname.copy()
        del info2cmdname_without_ALL['ALL']
        if info in list(info2cmdname_without_ALL.keys()):
            cmd_name = info2cmdname_without_ALL[info]
            query_cmd = self._moler_device.get_cmd(cmd_name=cmd_name, cmd_params={})
            queried_value = query_cmd()
            for key in queried_value:
                if queried_value[key] != expected_value:
                    raise ValueError("Current value ({}) does not equal expected value ({}).".format(
                        queried_value[key], expected_value))
        else:
            raise ValueError("'{}' is not supported. Supported parameters: {}".format(
                info, list(info2cmdname_without_ALL.keys())))

    def change_network_mode(self, network_mode_args):
        """
        Changes network mode of UE. Not sure all UEs support this method.

        :param network_mode_args: WCDMA_preferred, GSM_only, WCDMA_only, GSM_WCDMA_auto, CDMA_EvDo, CDMA_only, EvDo_only,
            Global, LTE_CDMA_EvDo, LTE_GSM_WCDMA, LTE_CDMA_EvDo_GSM_WCDMA, LTE_only, LTE_WCDMA
        :return: None
        """
        # TODO create moler cmd for chaning network mode. Add in next release.
        raise NotImplementedError

    def get_ue_id(self):
        """
        Return ue id specific for used ue-implementation/tool.

        :return: tool specific ue id
        """
        return self.ue_id
